import {
  collides,
  step,
  makeBricks,
  createState,
  brickHit,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('step: records the previous position for the brick sweep', () => {
  const state = createState(1);
  state.ball.x = 200;
  state.ball.y = 300;
  state.ball.vx = 60;
  state.ball.vy = 0;
  step(state, 1 / 60);
  assert.equal(state.ball.prevX, 200);
  assert.equal(state.ball.prevY, 300);
});

// --- Brick bounce (issue #1) ----------------------------------------------

// A lone brick at a known spot, reused by the bounce tests below.
function loneBrick() {
  return [{ x: 100, y: 100, w: 40, h: 20, alive: true }];
}

test('brickHit: head-on hit from below bounces the ball down', () => {
  const bricks = loneBrick();
  const ball = { x: 120, y: 125, r: 7, vx: 0, vy: -300, prevX: 120, prevY: 145 };
  const destroyed = brickHit(ball, bricks);
  assert.equal(destroyed.length, 1);
  assert.equal(bricks[0].alive, false);
  assert.equal(ball.vy, 300, 'vertical velocity should flip to down');
  assert.equal(ball.vx, 0, 'the other component is left untouched');
  assert.ok(ball.y - ball.r > 120, 'ball pushed back below the brick');
  assert.equal(collides(ball, bricks[0]), false, 'no overlap left behind');
});

test('brickHit: head-on hit from above bounces the ball up', () => {
  const bricks = loneBrick();
  const ball = { x: 120, y: 100, r: 7, vx: 0, vy: 300, prevX: 120, prevY: 88 };
  const destroyed = brickHit(ball, bricks);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vy, -300, 'vertical velocity should flip to up');
  assert.equal(ball.vx, 0);
  assert.ok(ball.y + ball.r < 100, 'ball pushed back above the brick');
  assert.equal(collides(ball, bricks[0]), false);
});

test('brickHit: side hit bounces the ball sideways', () => {
  const bricks = loneBrick();
  const ball = { x: 95, y: 110, r: 7, vx: 300, vy: 0, prevX: 82, prevY: 110 };
  const destroyed = brickHit(ball, bricks);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vx, -300, 'horizontal velocity should flip to the left');
  assert.equal(ball.vy, 0, 'the other component is left untouched');
  assert.ok(ball.x + ball.r < 100, 'ball pushed back left of the brick');
  assert.equal(collides(ball, bricks[0]), false);
});

test('brickHit: diagonal corner hit flips both axes', () => {
  const bricks = loneBrick();
  // The path enters the brick (expanded by the ball radius) exactly through
  // its bottom-right corner: equal penetration on both axes.
  const ball = { x: 157, y: 117, r: 7, vx: 300, vy: -300, prevX: 137, prevY: 137 };
  const destroyed = brickHit(ball, bricks);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, 300);
});

test('brickHit: a seam that overlaps two bricks bounces exactly once', () => {
  // Two bricks side by side; the 8 px gap is smaller than the 14 px ball, so
  // a straight shot through the seam touches both in the same pass.
  const bricks = [
    { x: 100, y: 100, w: 40, h: 20, alive: true },
    { x: 148, y: 100, w: 40, h: 20, alive: true },
  ];
  const ball = { x: 144, y: 120, r: 7, vx: 0, vy: -300, prevX: 144, prevY: 180 };
  const destroyed = brickHit(ball, bricks);
  assert.equal(destroyed.length, 2, 'both seam bricks are smashed');
  assert.equal(ball.vy, 300, 'vy flipped exactly once (twice would cancel)');
  assert.equal(ball.vx, 0, 'a straight shot stays straight');
  assert.ok(bricks.every((b) => !b.alive));
});

test('brickHit: a fast ball that jumps across a brick still bounces (sweep)', () => {
  const bricks = loneBrick();
  // 120 px of travel in one step, far more than the ~34 px needed to cross
  // the brick: with discrete per-frame checks alone the brick would be missed.
  const ball = { x: 120, y: 80, r: 7, vx: 0, vy: -300, prevX: 120, prevY: 200 };
  const destroyed = brickHit(ball, bricks);
  assert.equal(destroyed.length, 1, 'the crossed brick is still hit');
  assert.equal(ball.vy, 300, 'bounced off its underside');
  assert.ok(ball.y - ball.r > 120, 'pushed back below the brick');
});

test('brickHit: a ball that misses leaves bricks and velocity alone', () => {
  const bricks = loneBrick();
  const ball = { x: 300, y: 300, r: 7, vx: -300, vy: 300, prevX: 290, prevY: 290 };
  const destroyed = brickHit(ball, bricks);
  assert.equal(destroyed.length, 0);
  assert.equal(bricks[0].alive, true);
  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, 300);
});

