// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {

edits.newText:
// --- Brick collision (swept path, per-face bounce) ------------------------

// Margin used when pushing the ball out of a brick: the ball stops just short
// of touching it, so it can never start the next frame already overlapping
// (which would re-trigger the same bounce forever — a sticky bounce).
const EPS = 0.01;

// Which face of `brick` the ball (a circle of radius r) hits while travelling
// from (prevX, prevY) to its current position. The brick is tested expanded by
// the ball radius, and the segment between the two positions is swept, so a
// fast ball that jumps across a brick in a single frame is still caught (no
// tunnelling). Returns { face, t } with face one of 'left' | 'right' | 'top' |
// 'bottom' | 'corner' and t the entry time along the path, or null when the
// swept path never touches the brick.
function sweptFace(prevX, prevY, ball, brick) {
  const x0 = brick.x - ball.r;
  const x1 = brick.x + brick.w + ball.r;
  const y0 = brick.y - ball.r;
  const y1 = brick.y + brick.h + ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let enterX = -Infinity;
  let enterY = -Infinity;
  let faceX = null;
  let faceY = null;
  let tEnter = 0;
  let tExit = 1;

  // Sweep against the X slab (the brick expanded horizontally).
  if (Math.abs(dx) < 1e-12) {
    if (prevX < x0 || prevX > x1) return null; // moving parallel, off to the side
  } else {
    let ta = (x0 - prevX) / dx;
    let tb = (x1 - prevX) / dx;
    if (ta > tb) {
      const t = ta;
      ta = tb;
      tb = t;
    }
    enterX = ta;
    faceX = dx > 0 ? 'left' : 'right';
    tEnter = Math.max(tEnter, ta);
    tExit = Math.min(tExit, tb);
    if (tEnter > tExit) return null;
  }

  // Sweep against the Y slab (the brick expanded vertically).
  if (Math.abs(dy) < 1e-12) {
    if (prevY < y0 || prevY > y1) return null; // moving parallel, above or below
  } else {
    let ta = (y0 - prevY) / dy;
    let tb = (y1 - prevY) / dy;
    if (ta > tb) {
      const t = ta;
      ta = tb;
      tb = t;
    }
    enterY = ta;
    faceY = dy > 0 ? 'top' : 'bottom';
    tEnter = Math.max(tEnter, ta);
    tExit = Math.min(tExit, tb);
    if (tEnter > tExit) return null;
  }

  // The ball started the frame within a radius of the brick on BOTH axes (it
  // was pushed out to touch-but-not-overlap it). Only a real overlap counts
  // then, and the penetration decides the face.
  if (enterX < 0 && enterY < 0) {
    return collides(ball, brick) ? { face: penetrationFace(ball, brick), t: 0 } : null;
  }

  // The face is whichever slab decided the entry; equal entries mean the ball
  // came in straight at a corner.
  let face;
  if (enterX > enterY + 1e-9) face = faceX;
  else if (enterY > enterX + 1e-9) face = faceY;
  else face = 'corner';
  return { face, t: tEnter };
}

// Which face the ball penetrates least, when it currently overlaps `brick`.
// Equal penetrations mean a diagonal hit: report a corner.
function penetrationFace(ball, brick) {
  const left = ball.x + ball.r - brick.x;
  const right = brick.x + brick.w - (ball.x - ball.r);
  const top = ball.y + ball.r - brick.y;
  const bottom = brick.y + brick.h - (ball.y - ball.r);
  const minX = Math.min(left, right);
  const minY = Math.min(top, bottom);
  if (Math.abs(minX - minY) < 1e-9) return 'corner';
  if (minX < minY) return left < right ? 'left' : 'right';
  return top < bottom ? 'top' : 'bottom';
}

// Repositions the ball so it no longer overlaps `brick`, exiting through the
// face it hit (for a corner, diagonally away from the corner it came from).
function pushOut(ball, brick, face) {
  if (face === 'left') ball.x = brick.x - ball.r - EPS;
  else if (face === 'right') ball.x = brick.x + brick.w + ball.r + EPS;
  else if (face === 'top') ball.y = brick.y - ball.r - EPS;
  else if (face === 'bottom') ball.y = brick.y + brick.h + ball.r + EPS;
  else {
    const side = ball.x < brick.x + brick.w / 2 ? 'left' : 'right';
    const row = ball.y < brick.y + brick.h / 2 ? 'top' : 'bottom';
    ball.x = side === 'left' ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    ball.y = row === 'top' ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
  }
}

// Resolves every brick the ball's swept path touched this frame: each one is
// destroyed, the ball bounces off the FIRST face it hit (a single bounce per
// frame, so a seam that overlaps two bricks at once cannot double-flip and
// cancel itself out), and the ball is pushed back outside the brick so it
// cannot re-trigger the same bounce on the next frame.
// Returns the destroyed bricks, in the order they were checked.
export function brickHit(ball, bricks) {
  const prevX = ball.prevX ?? ball.x;
  const prevY = ball.prevY ?? ball.y;
  const destroyed = [];
  let nearest = null; // { brick, face } of the first face hit

  // Sweep pass: collect every live brick the swept path touches and remember
  // the earliest (smallest entry time) one, which decides the bounce.
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptFace(prevX, prevY, ball, brick);
    if (!hit) continue;
    brick.alive = false;
    destroyed.push(brick);
    if (!nearest || hit.t < nearest.t) nearest = { brick, face: hit.face, t: hit.t };
  }

  if (!nearest) return destroyed;

  // Bounce off the nearest face: flip only the axis that was hit, or both for
  // a corner. Exactly once — the other component stays as it was.
  const { brick, face } = nearest;
  if (face === 'left' || face === 'right') ball.vx = -ball.vx;
  else if (face === 'top' || face === 'bottom') ball.vy = -ball.vy;
  else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }

  // Push the ball back out of the brick it bounced off.
  pushOut(ball, brick, face);

  return destroyed;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Brick bounces are handled separately by brickHit()
// (still invoked from the render loop, see debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was before this move: brickHit() sweeps between
  // the two positions, so a fast ball cannot tunnel through a brick.
  ball.prevX = ball.x;
  ball.prevY = ball.y;

  ball.x += ball.vx * dt;

